  [412437] = { "敵に冷気の矢を放ち、$N1のFrostダメージを与えます。", nil, 0x2e8656ae, nil, "um" },
  [412507] = { "RendがBerserkerスタンスで使用できるようになり、Rendのダメージが$N1%増加し、さらにRendがダメージを与えるたびにAttack Powerの$N2%に等しい追加ダメージを与えます。", nil, 0x2d9ea468, nil, "um" },
  [412510] = { "対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員を$D1かけて体力を$N2回復し、それぞれに$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I1\n対象の時空間の位置を記録します。術者が与えたArcaneダメージの$N5%が、術者の現在のTemporal Beaconの対象それぞれへのクロノマンシーの治療に変換されます。この治療は自分に対しては$N6%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N7%減少します。", "$D1かけて体力を$N1回復しています。", 0x6a708596, 0x71292dfd, "uu" },
  [412513] = { "攻撃的なスタンスです。盾を装備している間、与えるダメージが$N1%増加し、ブロック率が$N2%上昇しますが、アーマーが$N3%、発生する脅威が$N4%減少します。さらに、自分を狙っていない敵に自動攻撃でダメージを与えると、得る怒りが$N5%増加します。\n\nGladiator Stanceで盾を装備している間は、他のスタンス専用のアビリティをすべて使用できます。", nil, 0xd9f8b649, nil, "um" },
  [412526] = { "敵にShadowダメージを与え、$D1の間、移動速度を低下させます。", "$D1の間、毎秒$N1のShadowダメージを受けます。\n移動速度が通常の$N3%に低下します。", 0xb24a12b1, 0xbc2e574c, "uu" },
  [412532] = { "敵にスペルフロストの矢を放ち、$N1のSpellfrostダメージを与え、$D1の間移動速度を$N2%低下させます。この呪文は対象のFrostとArcaneの耐性のうち低いほうで判定され、FrostとArcaneの両方のダメージとして扱われます。", "移動速度が$N1%低下しています。", 0x9762e582, 0xbe1d3d24, "uu" },
  [412538] = { "$D1ごとにFireダメージを与えます。", "$D1ごとに$N1のFireダメージを受けます。", 0x9b32ec1a, 0x83ee941a, "uu" },
